patches.new_text:
func _on_runtime_sfx_tree_exited():
				_sfx_active_count = max(0, _sfx_active_count - 1)

func play_sound_effect(stream, bus = "SFX"):
				if stream == null:
								return
				if bus != "SFX" and bus != "Drops":
								return
				if bus == "SFX" and not GameState.saved_stats.settings.enable_sfx:
								return
				if bus == "Drops" and not GameState.saved_stats.settings.enable_drops:
								return

				var now = OS.get_ticks_msec()
				var stream_key = str(bus) + ":" + str(stream.get_instance_id())
				if _sfx_last_play.has(stream_key) and now - _sfx_last_play[stream_key] < SFX_AGGREGATE_WINDOW_MS:
								return
				if _sfx_active_count >= SFX_MAX_CONCURRENT:
								return

				_sfx_last_play[stream_key] = now
				var sfx = sound_effect.instance()
				sfx.stream = stream
				sfx.bus = bus
				var audio = sfx.get_node("Audio")
				audio.pitch_scale = 1.0 + rand_range(-SFX_PITCH_VARIATION, SFX_PITCH_VARIATION)
				audio.volume_db = -rand_range(0.0, SFX_VOLUME_VARIATION_DB)
				sfx.connect("tree_exited", self, "_on_runtime_sfx_tree_exited")
				_sfx_active_count += 1
				get_tree().get_root().add_child(sfx)
